public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }

    boolean[][] visited = new boolean[n][n];
    boolean canTravel = dfs(start[0], start[1], end[0], end[1], visited, paths);

    return canTravel ? "can be travelled" : "cannot be travelled";
}

private static boolean dfs(int x, int y, int endX, int endY, boolean[][] visited, int[][] paths) {
    if (x == endX && y == endY) {
        return true;
    }

    visited[x][y] = true;

    for (int[] path : paths) {
        int nextX = path[0], nextY = path[1];
        if (!visited[nextX][nextY] && (nextX == x || nextY == y)) {
            if (dfs(nextX, nextY, endX, endY, visited, paths)) {
                return true;
            }
        }
    }

    return false;
}

public static String appx(String word1, String word2) {
