            throw new IllegalArgumentException("Date must be in the format 'MM dd yyyy'");
        }

        int month = Integer.parseInt(parts[0]);
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);

        if (month < 1 || month > 12) {
            throw new IllegalArgumentException("Month must be between 01 and 12");
        }
        if (day < 1 || day > 31) {
            throw new IllegalArgumentException("Day must be between 01 and 31");
        }

        java.util.Calendar calendar = java.util.Calendar.getInstance();
        calendar.set(year, month - 1, day); // month is 0-based in Calendar

        java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("MMMM d, yyyy 'is a' EEEE", java.util.Locale.ENGLISH);
        return sdf.format(calendar.getTime());
    } catch (Exception e) {
        return "Invalid date format: " + e.getMessage();
    }
}

