public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0 || k <= 0) {
        return false;
    }

    int[] remainderCount = new int[k];
    for (int num : arr) {
        int remainder = ((num % k) + k) % k; // Handle negative numbers
        remainderCount[remainder]++;
    }

    for (int i = 1; i <= k / 2; i++) {
        if (remainderCount[i] != remainderCount[k - i]) {
            return false;
        }
    }

    // Check if numbers with remainder 0 can be paired
    if (remainderCount[0] % 2 != 0) {
        return false;
    }

    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (edges == null || hasApple == null) {
        throw new IllegalArgumentException("Input arrays cannot be null");
    }
    if (n <= 0 || edges.length != n - 1 || hasApple.length != n) {
        throw new IllegalArgumentException("Invalid input sizes");
    }

    List<List<Integer>> tree = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        tree.add(new ArrayList<>());
    }
    for (int[] edge : edges) {
        tree.get(edge[0]).add(edge[1]);
        tree.get(edge[1]).add(edge[0]);
    }

    return dfs(0, -1, tree, hasApple) * 2;
}

private int dfs(int node, int parent, List<List<Integer>> tree, boolean[] hasApple) {
    int totalTime = 0;
    for (int child : tree.get(node)) {
        if (child == parent) continue; // Skip the parent node
        int childTime = dfs(child, node, tree, hasApple);
        if (childTime > 0 || hasApple[child]) {
            totalTime += childTime + 2; // Add 2 for the round trip
        }
    }
    return totalTime;
}

public String sortString(String s) {
    if (s == null || s.length() == 0) {
        return s;
    }

    int[] count = new int[26];
    for (char c : s.toCharArray()) {
        count[c - 'a']++;
    }

    StringBuilder result = new StringBuilder();
    boolean forward = true;

    while (result.length() < s.length()) {
        if (forward) {
            for (int i = 0; i < 26; i++) {
                if (count[i] > 0) {
                    result.append((char) (i + 'a'));
                    count[i]--;
                }
            }
        } else {
            for (int i = 25; i >= 0; i--) {
                if (count[i] > 0) {
                    result.append((char) (i + 'a'));
                    count[i]--;
                }
            }
        }
        forward = !forward;
    }

    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    int n = nums.length;
    boolean[][] dp = new boolean[n / 2 + 1][sum + 1];
    dp[0][0] = true;

    for (int num : nums) {
        for (int i = n / 2; i >= 1; i--) {
            for (int j = sum; j >= num; j--) {
                dp[i][j] = dp[i][j] || dp[i - 1][j - num];
            }
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        if (sum * i % n == 0 && dp[i][sum * i / n]) {
            return true;
        }
    }

    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length < 2) {
        throw new IllegalArgumentException("Cost array must contain at least two elements.");
    }

    int n = cost.length;
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }

    return Math.min(dp[n - 1], dp[n - 2]);
}

public int uniqueMorseRepresentations(String[] words) {
    if (words == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }

    String[] morseCodes = {
        ".-", "-...", "-.-.", "-..", ".", "..-.", "--.", "....", "..", ".---",
        "-.-", ".-..", "--", "-.", "---", ".--.", "--.-", ".-.", "...", "-",
        "..-", "...-", ".--", "-..-", "-.--", "--.."
    };

    Set<String> uniqueTransformations = new HashSet<>();

    try {
        for (String word : words) {
            if (word == null) {
                throw new IllegalArgumentException("Word in array cannot be null");
            }

            StringBuilder transformation = new StringBuilder();
            for (char c : word.toCharArray()) {
                if (c < 'a' || c > 'z') {
                    throw new IllegalArgumentException("Word contains invalid character: " + c);
                }
                transformation.append(morseCodes[c - 'a']);
            }
            uniqueTransformations.add(transformation.toString());
        }
    } catch (Exception e) {
        System.err.println("Error processing input: " + e.getMessage());
        return 0;
    }

    return uniqueTransformations.size();
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k < 0 || k > s.length()) {
        return false;
    }

    int totalSubstrings = 1 << k; // 2^k
    boolean[] found = new boolean[totalSubstrings];

    for (int i = 0; i <= s.length() - k; i++) {
        int value = 0;
        for (int j = 0; j < k; j++) {
            value = (value << 1) + (s.charAt(i + j) - '0');
        }
        found[value] = true;
    }

    for (boolean existence : found) {
        if (!existence) {
            return false;
        }
    }

    return true;
}

