public int minInsertions(String s) {
    int open = 0; // Tracks the number of unmatched '('
    int insertions = 0; // Tracks the number of insertions needed

    for (char c : s.toCharArray()) {
        if (c == '(') {
            open++;
        } else if (c == ')') {
            if (open > 0) {
                open--; // Match the ')'
            } else {
                insertions++; // Need to insert a '(' to match this ')'
            }
        }
    }

    // Each unmatched '(' needs a ')' to balance
    insertions += open;

    return insertions;
}

